package randGenerator

import (
	"math/rand"

	"github.com/CASP-Systems-BU/koala/api/tuple"
	"github.com/CASP-Systems-BU/koala/query/nexmark/config"
	"github.com/CASP-Systems-BU/koala/query/nexmark/models"
)

type RandGenerator struct {
	// Configuration of this generator
	config *config.NexmarkSourceConfig

	// Number of events generated by this generator
	outputEventNumber int64

	// Extra payload for each event
	extraPayload string

	// Total proportion of 3 kinds of events
	totalProportion int
}

func NewRandGenerator(
	cfg *config.NexmarkSourceConfig,
) *RandGenerator {

	return &RandGenerator{
		config:            cfg,
		outputEventNumber: cfg.OutputEventNumber,
		extraPayload:      string(make([]byte, cfg.ExtraPayloadSize)),
		totalProportion:   cfg.PersonProportion + cfg.AuctionProportion + cfg.BidProportion,
	}
}

// Generate PersonEvent according to replicaID and parallelism
func (g *RandGenerator) NextPerson(
	replicaID int64,
	parallelism int,
	random *rand.Rand,
) (tuple.Tuple, error) {
	// How many PersonEvent is generated by all source tasks
	totalPersonEventGenerated := g.outputEventNumber*int64(
		parallelism,
	) + replicaID

	newEventID := GetEventCountSoFar(
		config.Person,
		g.config.PersonProportion,
		totalPersonEventGenerated,
		g.totalProportion,
		g.config.PersonProportion,
		g.config.AuctionProportion,
	)

	eventTimestamp := getEventTime(newEventID, g.config.InterEventDelay)

	event := NextPerson(newEventID, random, eventTimestamp, g.config)
	event.V8 = g.extraPayload
	g.outputEventNumber++

	return event, nil
}

// Generate AuctionEvent according to replicaID and parallelism
func (g *RandGenerator) NextAuction(
	replicaID int64,
	parallelism int,
	random *rand.Rand,
) (tuple.Tuple, error) {
	// How many AuctionEvent is generated by all source tasks
	totalAuctionEventGenerated := g.outputEventNumber*int64(
		parallelism,
	) + replicaID

	newEventID := GetEventCountSoFar(
		config.Auction,
		g.config.AuctionProportion,
		totalAuctionEventGenerated,
		g.totalProportion,
		g.config.PersonProportion,
		g.config.AuctionProportion,
	)

	eventTimestamp := getEventTime(newEventID, g.config.InterEventDelay)

	event := NextAuction(newEventID, random, eventTimestamp, g.config)
	event.V10 = g.extraPayload
	g.outputEventNumber++

	return event, nil
}

