// Generate ClosedAuction according to replicaID and parallelism
func (g *RandGenerator) NextClosedAuction(
	replicaID int64,
	parallelism int,
	random *rand.Rand,
) (tuple.Tuple, error) {

	// How many ClosedAuction is generated by all source tasks
	totalEventGenerated := g.outputEventNumber*int64(parallelism) + replicaID

	newEventID := GetEventCountSoFar(
		config.Auction,
		g.config.BidProportion,
		totalEventGenerated,
		g.totalProportion,
		g.config.PersonProportion,
		g.config.AuctionProportion,
	)

	eventTimestamp := getEventTime(newEventID, g.config.InterEventDelay)
	var event *models.ClosedAuctionEvent
	if g.config.WarmupRun {
		event = NextWarmupClosedAuction(newEventID, random, eventTimestamp, g.config, totalEventGenerated, g.totalProportion)
	} else {
		event = NextClosedAuction(newEventID, random, eventTimestamp, g.config)
	}

	event.V6 = g.extraPayload
	g.outputEventNumber++

	return event, nil
}

// Calculate for each type, where should their eventCount start
func StartBase(
	eventType config.EventType,
	personProportion int,
	auctionProportion int,
) int64 {
	switch eventType {
	case config.Person:
		return 0
	case config.Auction:
		return int64(personProportion)
	default:
		return int64(personProportion + auctionProportion)
	}
}

// Calculate what the current eventID(shared among all 3 kinds of event) is
func GetEventCountSoFar(
	eventType config.EventType,
	eventProportion int,
	eventGenerated int64,
	totalProportion int,
	personProportion int,
	auctionProportion int,
) int64 {
	numRoundGenerated := eventGenerated / int64(eventProportion)
	positionInThisRound := eventGenerated % int64(eventProportion)

	return numRoundGenerated*int64(
		totalProportion,
	) + StartBase(
		eventType,
		personProportion,
		auctionProportion,
	) + positionInThisRound
}
